parameters.jsCode:
// Prepare customer review solicitation metadata
const body = $input.item.json.body || $input.item.json;

const customerName = (body.customer_name || body.name || 'Valued Customer').trim();
const email = (body.customer_email || body.email || '').trim().toLowerCase();
const phone = (body.customer_phone || body.phone || '').trim();
const serviceName = (body.service_name || 'your recent service').trim();
const technicianName = (body.technician_name || 'our team').trim();
const invoiceId = (body.invoice_id || 'INV-' + Date.now()).trim();
const googleReviewUrl = body.google_review_url || 'https://g.page/r/your-google-business-review/review';
const webhookBaseUrl = body.webhook_base_url || 'https://automations.ashflow.site/webhook/submit-customer-rating';

return {
  json: {
    customer_name: customerName,
    customer_email: email,
    customer_phone: phone,
    service_name: serviceName,
    technician_name: technicianName,
    invoice_id: invoiceId,
    google_review_url: googleReviewUrl,
    rating_url_5: `${webhookBaseUrl}?invoice_id=${encodeURIComponent(invoiceId)}&email=${encodeURIComponent(email)}&name=${encodeURIComponent(customerName)}&rating=5`,
    rating_url_4: `${webhookBaseUrl}?invoice_id=${encodeURIComponent(invoiceId)}&email=${encodeURIComponent(email)}&name=${encodeURIComponent(customerName)}&rating=4`,
    rating_url_3: `${webhookBaseUrl}?invoice_id=${encodeURIComponent(invoiceId)}&email=${encodeURIComponent(email)}&name=${encodeURIComponent(customerName)}&rating=3`,
    rating_url_2: `${webhookBaseUrl}?invoice_id=${encodeURIComponent(invoiceId)}&email=${encodeURIComponent(email)}&name=${encodeURIComponent(customerName)}&rating=2`,
    dispatched_at: new Date().toISOString()
  }
};

// Extract query parameters from 1-click rating link
const query = $input.item.json.query || $input.item.json;

const rating = parseInt(query.rating || '5', 10);
const invoiceId = (query.invoice_id || 'UNKNOWN').trim();
const customerName = (query.name || 'Valued Customer').trim();
const customerEmail = (query.email || '').trim().toLowerCase();
const feedback = (query.feedback || query.comments || '').trim();
const googleReviewUrl = query.google_review_url || 'https://g.page/r/your-google-business-review/review';

return {
  json: {
    rating,
    invoice_id: invoiceId,
    customer_name: customerName,
    customer_email: customerEmail,
    feedback,
    google_review_url: googleReviewUrl,
    is_promoter: rating >= 4,
    submitted_at: new Date().toISOString()
  }
};

